"""The four-center seventh cut and the residue algebra generated by its relations."""

from functools import cache, reduce
from itertools import product
from operator import xor

from verify_klein_center_lift import add_multiple, echelon
from verify_rank_fifteen_sixth_center_minors import MODULUS, TraceJet, relations
from verify_rank_fifteen_two_sided_cut import overlap_rows, store_projection
from verify_rank_fifteen_variable_zero_disk import BASE_POINT, F9, center_data
from verify_rank_fourteen_all_ordinary import DIMENSIONS, saturated_projection
from verify_rank_fourteen_central_cut import quotient_layers
from verify_rank_fourteen_geometric_reduction import Scalar


def evaluate(poly):
    remainder = poly % MODULUS
    return F9(int(remainder[0]) % 3) + (int(remainder[1]) % 3)*BASE_POINT


def residue_scalar(v):
    return Scalar(evaluate(v.coeffs[0])/evaluate(v.den))


def seed_layers(start, limit, windows, centers, dims, right, jet, specialize):
    words = {(0, h): [()] if h == 0 else [] for h in range(4)}
    for h in range(4):
        dims[start, 0, h] = len(words[0, h])
    losses = []

    def project(n, h, rows, size):
        free, projection, loss = saturated_projection(rows, size, DIMENSIONS[n][h], jet)
        losses.append(loss)
        columns = [w+(a,) for a in range(4) for w in words[n-1, h^a]]
        words[n, h] = [columns[j] for j in free]
        dims[start, n, h] = len(free)
        offset = 0
        for a in range(4):
            end = offset+len(words[n-1, h^a])
            right[start, n, h, a] = [
                {k: specialize(v) for k, v in row.items() if v.unit()}
                for row in projection[offset:end]
            ]
            offset = end
        assert offset == size
        return free, projection

    for n in quotient_layers(windows, centers, start, limit, jet.constant(1), project):
        assert max(losses) == (0, 0, 0, 2, 4, 2, 2)[n-1]
        jet.precision -= max(losses)
        assert jet.precision > 0
        losses.clear()
    return words


def prepend_tables(start, limit, words, right):
    @cache
    def image(word):
        if not word:
            return {0: Scalar(F9.one())}
        h = reduce(xor, word, 0)
        out = {}
        for j, v in image(word[:-1]).items():
            add_multiple(out, right[start, len(word), h, word[-1]][j], v)
        return out

    left = {}
    for n in range(1, limit+1):
        for h, a in product(range(4), repeat=2):
            left[start, n, h, a] = [image((a,)+w) for w in words[(start+1)%4][n-1, h^a]]
    return left


def overlap(n, p, h, dims, left, right):
    ends, beginnings, width, rows = overlap_rows(n, p, h, dims, left, right)
    pivots = echelon(rows)
    free = [j for j in range(width) if j not in pivots]
    indices = {j: k for k, j in enumerate(free)}
    projected = [{indices[j]: Scalar(F9.one())} if j in indices else
                 {indices[k]: -v for k, v in pivots[j].items() if k != j} for j in range(width)]
    store_projection(n, p, h, dims, left, right, ends, beginnings, free, projected)
    return len(free)


def verify(jet=TraceJet, build_relations=relations, specialize=residue_scalar):
    limit = 7
    windows, _, _, centers = center_data(15, jet, build_relations)
    dims, left, right, words = {}, {}, {}, []
    print("Computed exact variable-trace center data.", flush=True)
    for start in range(4):
        jet.precision = 11
        words.append(seed_layers(start, limit, windows, centers, dims, right, jet, specialize))
        assert jet.precision == 1
        print("Seventh central quotient verified at start", start, flush=True)
    for start in range(4):
        left.update(prepend_tables(start, limit, words, right))
    for n in range(limit+1, 14):
        for p, h in product(range(4), repeat=2):
            dims[p, n, h] = overlap(n, p, h, dims, left, right)
        profiles = [tuple(dims[p, n, h] for h in range(4)) for p in range(4)]
        expected = (6,)*4 if n == 9 else DIMENSIONS[n]
        assert profiles == [expected]*4
        print("Degree", n, "residue algebra", profiles[0], flush=True)


if __name__ == "__main__":
    verify()
